376:     // strip whitespace
377:     rtn = type.replace(/\s+/g, '').toLowerCase();
378:     if (rtn === 'pointer') {
379:       // legacy "pointer" being used :(
380:       rtn = exports.refType(exports.types.void); // void *
381:     } else if (rtn === 'string') {
382:       rtn = exports.types.CString; // special char * type
383:     } else {
384:       var refCount = 0;
385:       rtn = rtn.replace(/\*/g, function() {
386:         refCount++;
387:         return '';
388:       });
389:       // allow string names to be passed in
390:       rtn = exports.types[rtn];
391:       if (refCount > 0) {
